  const isZh = useIsZh();
  const buildTags = () =>
    isZh ? ['前端', 'Vue', 'React', 'TypeScript'] : ['Frontend', 'Vue', 'React', 'TypeScript'];
  const [tags, setTags] = useState(buildTags);
